codeExample:
interface User {
  name: string;
  age: number;
}

// The Mapped Type Factory:
// 1. Loops through all keys of T
// 2. Assigns boolean as the new value for every key
type Booleanify<T> = {
  [K in keyof T]: boolean;
};

// We pass User into the factory
type UserValidationMap = Booleanify<User>;

/* Resulting Type:
  {
    name: boolean;
    age: boolean;
  }
*/

const isValid: UserValidationMap = {
  name: true,
  age: false
};
